scriptdefs
= Route101_EventScript_HideMapNamePopup
setflag FLAG_HIDE_MAP_NAME_POPUP
setvar VAR_ROUTE101_STATE 1
end
= Route101_EventScript_PreventExitNorth
lockall
msgbox	W-Wohin gehst du?! Lass mich nicht allein!
closemessage
applymovement LOCALID_PLAYER Route101_Movement_PreventExitNorth
waitmovement 0
releaseall
end
= Route101_EventScript_PreventExitWest
lockall
msgbox	W-Wohin gehst du?! Lass mich nicht allein!
closemessage
applymovement LOCALID_PLAYER Route101_Movement_PreventExitWest
waitmovement 0
releaseall
end
= Route101_EventScript_PreventExitSouth
lockall
msgbox	W-Wohin gehst du?! Lass mich nicht allein!
closemessage
applymovement LOCALID_PLAYER Route101_Movement_PreventExitSouth
waitmovement 0
releaseall
end
= Route101_EventScript_StartBirchRescue
lockall
playbgm MUS_HELP TRUE
msgbox	H-Hilfe!
closemessage
setobjectxy LOCALID_ROUTE101_BIRCH 0 15
setobjectxy LOCALID_ROUTE101_ZIGZAGOON 0 16
applymovement LOCALID_PLAYER Route101_Movement_EnterScene
applymovement LOCALID_ROUTE101_BIRCH Route101_Movement_BirchRunAway1
applymovement LOCALID_ROUTE101_ZIGZAGOON Route101_Movement_ZigzagoonChase1
waitmovement 0
applymovement LOCALID_ROUTE101_ZIGZAGOON Route101_Movement_ZigzagoonChaseInCircles
applymovement LOCALID_ROUTE101_BIRCH Route101_Movement_BirchRunInCircles
waitmovement 0
applymovement LOCALID_ROUTE101_BIRCH Common_Movement_WalkInPlaceFasterRight
waitmovement 0
applymovement LOCALID_ROUTE101_ZIGZAGOON Route101_Movement_ZigzagoonFaceBirch
applymovement LOCALID_ROUTE101_BIRCH Route101_Movement_BirchFaceZigzagoon
waitmovement 0
msgbox	Hallo! Du dort drüben! Bitte! Hilf mir!In meiner TASCHE! Da ist ein POKéBALL!
closemessage
setvar VAR_ROUTE101_STATE 2
releaseall
end
= Route101_EventScript_Boy
msgbox	Im hohen Gras können wilde POKéMON plötzlich auftauchen.Wenn du POKéMON fangen möchtest, musst du ins hohe Gras gehen und dort suchen.
end
= ProfBirch_EventScript_RatePokedexOrRegister
lock
faceplayer
goto_if_unset FLAG_HAS_MATCH_CALL ProfBirch_EventScript_AskRatePokedex
goto_if_unset FLAG_ENABLE_PROF_BIRCH_MATCH_CALL EventScript_RegisterProfBirch
goto ProfBirch_EventScript_AskRatePokedex
= ProfBirch_EventScript_AskRatePokedex
msgboxyesno	PROF. BIRK: Ah, PLAYER!Möchtest du wissen, wie weit du mit deinem POKéDEX bist?
goto_if_eq VAR_RESULT NO ProfBirch_EventScript_DeclineRating
call ProfBirch_EventScript_RatePokedex
release
end
= ProfBirch_EventScript_RatePokedex
setvar VAR_0x8004 0
specialvar VAR_RESULT ScriptGetPokedexInfo
copyvar VAR_0x8008 VAR_0x8005
copyvar VAR_0x8009 VAR_0x8006
copyvar VAR_0x800A VAR_RESULT
buffernumberstring STR_VAR_1 VAR_0x8008  @ Num Hoenn gesehen
buffernumberstring STR_VAR_2 VAR_0x8009  @ Num Hoenn gefangen
msgbox	Hmhm …Du hast also STR_VAR_1 POKéMON gesehen und STR_VAR_2 POKéMON gefangen …
call ProfBirch_EventScript_ShowRatingMessage
goto_if_eq VAR_0x800A 0 Common_EventScript_NopReturn  @ Nationaler Pokédex nicht aktiviert
setvar VAR_0x8004 1
specialvar VAR_RESULT ScriptGetPokedexInfo
copyvar VAR_0x8008 VAR_0x8005
copyvar VAR_0x8009 VAR_0x8006
buffernumberstring STR_VAR_1 VAR_0x8008  @ National gesehen
buffernumberstring STR_VAR_2 VAR_0x8009  @ National gefangen
msgbox	Hmhm … Auf nationaler Ebene …Du hast STR_VAR_1 POKéMON gesehen und STR_VAR_2 POKéMON gefangen …
return
= ProfBirch_EventScript_ShowRatingMessage
copyvar VAR_0x8004 VAR_0x8009
special ShowPokedexRatingMessage
waitmessage
waitbuttonpress
return
= ProfBirch_EventScript_DeclineRating
msgbox	Hm? Du hast noch nicht genug POKéMON gefangen, als dass sich das lohnen würde.
release
end
= Route101_EventScript_BirchsBag
lock
faceplayer
setflag FLAG_SYS_POKEMON_GET
setflag FLAG_RESCUED_BIRCH
fadescreen FADE_TO_BLACK
removeobject LOCALID_ROUTE101_ZIGZAGOON
setobjectxy LOCALID_PLAYER 6 13
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterLeft
waitmovement 0
special ChooseStarter
applymovement LOCALID_ROUTE101_BIRCH Route101_Movement_BirchApproachPlayer
waitmovement 0
msgbox	PROF. BIRK: Puh …Ich war im hohen Gras und habe wilde POKéMON untersucht, als ich plötzlich angegriffen wurde.Du hast mich gerettet. Vielen Dank!Oh?Hallo, du bist PLAYER!Hier ist nicht der richtige Ort zum Reden. Komm später in mein POKéMON-LABOR, ja?
special HealPlayerParty
setflag FLAG_HIDE_ROUTE_101_BIRCH_ZIGZAGOON_BATTLE
clearflag FLAG_HIDE_LITTLEROOT_TOWN_BIRCHS_LAB_BIRCH
setflag FLAG_HIDE_ROUTE_101_BIRCH_STARTERS_BAG
setvar VAR_BIRCH_LAB_STATE 2
setvar VAR_ROUTE101_STATE 3
clearflag FLAG_HIDE_MAP_NAME_POPUP
checkplayergender
call_if_eq VAR_RESULT MALE Route101_EventScript_HideMayInBedroom
call_if_eq VAR_RESULT FEMALE Route101_EventScript_HideBrendanInBedroom
warp LittlerootTown_ProfessorBirchsLab 6 5
waitstate
release
end
= Route101_EventScript_HideBrendanInBedroom
setflag FLAG_HIDE_LITTLEROOT_TOWN_BRENDANS_HOUSE_RIVAL_BEDROOM
return
= Route101_EventScript_HideMayInBedroom
setflag FLAG_HIDE_LITTLEROOT_TOWN_MAYS_HOUSE_RIVAL_BEDROOM
return
= Route101_EventScript_Youngster
msgbox	Wenn deine POKéMON müde werden, bring sie in ein POKéMON-CENTER.Im nahe gelegenen BLÜTENBURG CITY gibt es ein POKéMON-CENTER.
end
